statement:
\begin{lemma}\label{lem:low-degree}
Let $m\ge2$ be real and let $h:\{0,1\}^J\to\{0,1\}$ satisfy
$I_i(h)\le I(h)/m$ for every $i\in J$. If
\[
  k=\frac{\sigma\log m}{64},
\]
then
\begin{equation}\label{eq:low-degree}
  \sum_{1\le |S|\le k}\widehat h(S)^2\le m^{-1/4}I(h).
\end{equation}
Every degree cutoff is interpreted literally for integer degrees $|S|$;
in particular, the sum is empty when $k<1$.
\end{lemma}

\begin{lemma}[Exact averaging over a restriction]
\label{lem:restriction}
Let $F\subseteq E_n$, put $H=E_n\setminus F$, and, for
$y\in\{0,1\}^{H}$, let $f_y(x)=f(x,y)$ for
$x\in\{0,1\}^{F}$.  If $y$ has the Bernoulli-$p$ product law, then,
for every real $k>0$,
\begin{align}
 \E_y\sum_{\substack{A\subseteq F\\1\le |A|\le k}}
        \widehat{f_y}(A)^2
 &=\sum_{\substack{S\subseteq E_n\\1\le|S\cap F|\le k}}
        \widehat f(S)^2,
 \label{eq:restriction-mass}\\
 \E_y I(f_y)&=\sum_{e\in F}I_e(f).
 \label{eq:restriction-influence}
\end{align}
\end{lemma}

\begin{proposition}[The block estimate]
\label{prop:block}
Let $3\le m\le n$ be an integer, let $B$ be uniform among the
$m$-element subsets of $[n]$, and set
\[
 F_B=\{e\in E_n:e\cap B\ne\varnothing\},
 \qquad k=\frac{\sigma\log m}{64}.
\]
Then
\begin{equation}
 \sum_{S\subseteq E_n}
 \Pr_B\{1\le |S\cap F_B|\le k\}\widehat f(S)^2
 \le \frac{2m}{n}\,m^{-1/4}I(f).
 \label{eq:block-average}
\end{equation}
\end{proposition}

\begin{lemma}[Capturing low Fourier levels]
\label{lem:block-capture}
Suppose $t=\log n\ge16$, and put
\[
 m=\lfloor\sqrt n\rfloor,
 \qquad k=\frac{\sigma\log m}{64}.
\]
Then
\begin{equation}
 \sum_{\substack{S\subseteq E_n\\1\le |S|\le k^2/2}}
       \widehat f(S)^2
 \le 4m^{-1/4}I(f).
 \label{eq:captured-mass}
\end{equation}
\end{lemma}

\begin{theorem}[Friedgut--Kalai sharp-threshold conjecture]
\label{thm:threshold}
For every integer $n\ge2$, every nontrivial increasing family $\mathcal P$ of graphs on $n$ vertices invariant under all vertex permutations, and every $0<\varepsilon<1/2$,
\begin{equation}
\label{eq:threshold}
 p_{1-\varepsilon}(\mathcal P)-p_\varepsilon(\mathcal P)
 \le \frac{2^{19}}{(\log n)^2}\log\frac1{2\varepsilon}.
\end{equation}
\end{theorem}

\begin{theorem}[Variance and influence]
\label{thm:variance}
For every integer $n\ge2$, every Boolean function $f$ on $E_n$ invariant under vertex permutations, and every $0<p<1$,
\begin{equation}
\label{eq:variance}
 \Var_p(f)\le\frac{2^{17}}{(\log n)^2}I_p(f).
\end{equation}
No monotonicity assumption is needed.
\end{theorem}

\begin{lemma}[Rank-layer limit]
\label{lem:rank-layer}
There is an integer $D_0$ such that, for every fixed even $D\ge D_0$,
the following assertion holds as $q$ tends to infinity through odd
primes. Let $X_i$, $i\in I$, and $Y_j$, $j\in J$, be independent
uniform elements of $\mathcal S_D$. For every set
$B\subseteq\mathscr C$ and every choice of signs
$\xi_{ij}\in\{1,-1\}$ on $B$,
\begin{equation}
 \E\prod_{(i,j)\in B}K_{\xi_{ij}}(X_i-Y_j)
 =\E_\eta\prod_{j\in J}
 \prod_{\substack{e=\{i,k\}\subset j\\(i,j),(k,j)\in B}}
 \bigl(1+c_0\eta_e\xi_{ij}\xi_{kj}\bigr)+o(1),
 \label{eq:rank-layer}
\end{equation}
where the $\eta_e$, $e\in E$, are independent uniform signs. The error
is uniform over all such $B$ and sign choices. The same assertion
holds with $Y_j-X_i$ in place of $X_i-Y_j$.
\end{lemma}

\begin{lemma}[Coordinate expansion]
\label{lem:kernel-expansion}
Assume Equation~\eqref{eq:kernel-zero-moments} and fix an even dimension
as in Lemma~\ref{lem:rank-layer}. For fixed type laws and activation
laws,
\begin{align}
 t_{I,J}(W_q)&=1+
 \sum_{a:I\to\mathcal A\,,\ b:J\to\mathcal B}
 \left(\prod_{i\in I}\pi_{a(i)}\right)
 \left(\prod_{j\in J}\nu_{b(j)}\right)C_A(a,b)+o(1).
 \label{eq:kernel-expansion}
\end{align}
The corresponding formula for $W_q^\top$ has type maps
$b:I\to\mathcal B$, $a:J\to\mathcal A$ and the corner factors
$A_{a(j)b(i)}$.
\end{lemma}

\begin{lemma}[Support forcing]
\label{lem:kernel-support}
At the identity type assignments $a(i)=i$, $b(j)=j$, the sum in
Equation~\eqref{eq:kernel-coefficient} for the base laws has exactly one
nonzero term. Its labels and value are
\begin{equation}
 \alpha_e=U_e\quad(e\in E),\qquad
 C_{A^{\mathrm{base}}}(\mathrm{id},\mathrm{id})
 =-(\theta/2)^{66}.
 \label{eq:kernel-negative-term}
\end{equation}
\end{lemma}

\begin{lemma}[Pinning by vertex and pair scores]
\label{lem:pinning}
Let $F=(P\sqcup Q,L)$ be a finite bipartite graph for which color
refinement, starting with the two part colors, becomes discrete within
each part. There are real vertex scores $s_t$, $t\in P\sqcup Q$,
and pair scores $s_{ab}$, $(a,b)\in P\times Q$, such that the identity
is the unique maximizer of
\begin{equation}
 \mathcal Q(f)=\sum_{u\in P\sqcup Q}s_{f(u)}
              +\sum_{\{u,v\}\in L,\ u\in P}s_{f(u)f(v)}
 \label{eq:kernel-pinning-score}
\end{equation}
over \emph{all} maps $f$ preserving the two parts. In particular the
maximum has a positive gap from every other such map; no injectivity
or adjacency-preservation condition is imposed.
\end{lemma}

\begin{proposition}
\label{prop:negative-kernel}
Assuming Lemma~\ref{lem:rank-layer}, there is a symmetric kernel
$U:\Omega\times\Omega\to[0,1]$ on a finite probability space with
mean $\mu>0$ such that
\begin{equation}
 t(H,U)<\mu^{66}.
 \label{eq:kernel-symmetric-gap}
\end{equation}
\end{proposition}

\begin{lemma}[Transfer to a finite simple host]
\label{lem:finite-host}
Suppose $U$ is a symmetric $[0,1]$-valued kernel on a finite
probability space, $\mu=\E U>0$, and
\[
 \tau=t(H,U),\qquad \Delta=\mu^{66}-\tau>0.
\]
For any integer
\begin{equation}
 n>\frac{595+66\mu^{66}}{\Delta},
 \label{eq:kernel-host-size}
\end{equation}
there is a finite simple graph $G$ on $n$ vertices with
$t(H,G)<p(G)^{66}$.
\end{lemma}

\begin{lemma}[Lagrangian counting formulas]
\label{lem:lagrangian-counts}
In a symplectic $2N$-space, the following formulas hold.
\begin{enumerate}
 \item The number of Lagrangians is $L_N$.
 \item A fixed isotropic $t$-space is contained in exactly $L_{N-t}$
 Lagrangians.  Consequently its containment probability and the number of
 isotropic $t$-spaces are, respectively,
 \begin{equation}
 \vartheta_N(t)=\frac{L_{N-t}}{L_N},\qquad
 I_N(t)=\frac{L_N}{L_{N-t}}\genfrac{[}{]}{0pt}{}{N}{t}_q.
 \label{eq:orbits-containment}
 \end{equation}
 \item For a fixed Lagrangian $A$, the number of Lagrangians $B$ with
 $\dim(A\cap B)=h$ is $\genfrac{[}{]}{0pt}{}{N}{h}_q q^{b(N-h)}$.  Thus
 \begin{equation}
 \pi_{N,h}:=\P\{\dim(A\cap B)=h\}
 =\frac{\genfrac{[}{]}{0pt}{}{N}{h}_q q^{b(N-h)}}{L_N}.
 \label{eq:orbits-pair-probability}
 \end{equation}
 All ordered pairs with the same intersection dimension belong to one
 symplectic orbit.
\end{enumerate}
For fixed $N$, these formulas give
\begin{align}
 L_N&=(1+O_N(q^{-1}))q^{b(N)},
 &\genfrac{[}{]}{0pt}{}{n}{t}_q&=(1+O_n(q^{-1}))q^{t(n-t)},\\
 \vartheta_N(t)&\asymp_N q^{-Nt+\binom t2},
 &I_N(t)&\asymp_N q^{2Nt-(3t^2-t)/2},\\
 \pi_{N,h}&\asymp_N q^{-b(h)}.
 \label{eq:orbits-count-exponents}
\end{align}
\end{lemma}

\begin{proposition}[Mass of ordered triple orbits]
\label{prop:triple-orbits}
For three independent uniform Lagrangians, every feasible dimensional
profile has probability $O_D(q^{-C})$.  More strongly, there is a constant
$\kappa_D>0$, independent of $q$ and of the particular orbit, such that
for every occurring ordered symplectic orbit $\mathcal O$ of that profile,
\begin{equation}
 \kappa_D q^{-C}\le
 \P\{(L_1,L_2,L_3)\in\mathcal O\}
 \le \kappa_D^{-1}q^{-C}.
 \label{eq:orbits-orbit-mass}
\end{equation}
The constant can be chosen for all odd primes.  Moreover, conditional on
any fixed ordered pair having intersection dimension $h$, the probability
that an independent third Lagrangian completes a specified dimensional
profile is
\begin{equation}
 O_D(q^{-C+b(h)}).
 \label{eq:orbits-conditional-profile}
\end{equation}
\end{proposition}

\begin{lemma}\label{lem:planted-subspace-cost}
For three independent uniform $r'$-subspaces of a $d$-space, the
event of common intersection zero, opposite pair dimensions $p_i$,
and span codimension $v$ has probability
\begin{equation}\label{eq:planted-subspace-cost}
 O\left(q^{-\delta P-\sum_i p_i^2-vw}\right).
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:planted-difference-image}
Let $A_1,A_2,A_3$ be arbitrary subspaces of a vector space, put
$Q_i=A_j\cap A_k$, and put $V=A_1\cap A_2\cap A_3$.
The image of the cyclic difference map on symmetric forms is exactly
\begin{equation}\label{eq:planted-difference-image}
 \left\{(D_1,D_2,D_3):
       D_1|_V+D_2|_V+D_3|_V=0\right\}.
\end{equation}
Its codimension in the product of the three form spaces on the
$Q_i$ is $b(\dim V)$.  Independent uniform $F_i$ give the uniform
law on this image.
\end{lemma}

\begin{lemma}[At most two active incidences]\label{lem:two-active-gain}
For two active incidences whose point Lagrangians meet in dimension
$h$, a valid gain exponent is
\begin{equation}\label{eq:planted-two-active-gain}
 g_2(h)
 =\max_{\substack{p+t=h\,;\ 0\le t\le p\le r}}
      \{b(h)-p^2-b(t)\}
 =b(\lfloor h/2\rfloor).
\end{equation}
For zero or one active incidence, the face factor is exactly one.
\end{lemma}

\begin{proposition}[Global profile cost]\label{prop:global-cost}
For every prescribed profile, its probability is $O_D(q^{-\mathcal C})$,
where
\begin{equation}\label{eq:global-cost}
 \mathcal C=\frac12\left(
 \sum_{j\in J}C_j-\sum_{e\in E}(1-a_e)b(h_e)\right).
\end{equation}
\end{proposition}

\begin{lemma}[Faces with at most two active incidences]\label{lem:tail-lower-active}
Let $h=\max_{e\subset j}h_e$.  If $j$ has at most two active incidences,
then
\begin{equation}\label{eq:tail-lower-active}
 S_j\ge0,
 \qquad S_j\ge\frac{h^2}{24}-\frac h{12}.
\end{equation}
Equality $S_j=0$ requires $c_j=0$ and either all three pair dimensions
zero or exactly one pair dimension equal to $2$.  The latter case
requires exactly two active incidences, at that pair's endpoints.
\end{lemma}

\begin{lemma}[Coercivity]\label{lem:coercivity}
Every tuple satisfying Equation~\eqref{eq:tail-feasible} satisfies
\begin{equation}\label{eq:coercivity}
 Q\ge\frac1{342}(P^2+T^2+\delta^2).
\end{equation}
\end{lemma}

\begin{lemma}[Profiles not separated by the first cost]\label{lem:tail-residue}
There is an even-dimensional threshold such that, for every even $D$
above it, every feasible profile and every activity set for which
$\sum_jg_j\ge\mathcal C$ has the following properties:
\begin{equation}\label{eq:tail-residual-profile}
 c_j=0\quad(j\in J),\qquad h_e\in\{0,2\}\quad(e\in E),
 \qquad\sum_jg_j\le\frac23\sum_{e\in E}b(h_e).
\end{equation}
\end{lemma}

\begin{proposition}[Vanishing singular contribution]\label{prop:singular-tail}
For every sufficiently large even $D=2r$ and every activity set
$B\subseteq\mathscr C$,
\begin{equation}\label{eq:tail-vanishing}
 \E_{L,Y}\left[
 \1_{\{\exists e=\{i,k\}\in E:\,\dim(L_i\cap L_k)>0\}}
 \prod_{(i,j)\in B}J(L_i,Y_j)\right]=o(1)
\end{equation}
as $q\to\infty$ through odd primes, with $D$ fixed.  The dimension
threshold can be chosen for all activity sets simultaneously.
\end{proposition}

\begin{lemma}[Subspaces and symmetric matrices]
\label{lem:symmetric-counts}
For $0\leq k\leq n$, the number of $k$-dimensional subspaces of
$\F_q^n$ is
\begin{equation}
\label{eq:transverse-grassmann}
 \genfrac{[}{]}{0pt}{}{n}{k}_q
 =\prod_{a=0}^{k-1}\frac{q^n-q^a}{q^k-q^a}
 =q^{k(n-k)}(1+O(q^{-1})).
\end{equation}
For a uniform matrix $M\in\mathcal S_n$, with $n\geq 1$,
\[
 \P(M\text{ is nonsingular})=1-O(q^{-1}),\qquad
 \P(\chi(\det M)=\xi)=\frac12+O(q^{-1})
 \quad(\xi\in\{+1,-1\}).
\]
For $1\leq k\leq n$, the probability of rank $k$ and prescribed
discriminant sign is
\begin{equation}
\label{eq:transverse-signed-rank}
 \left(\frac12+O(q^{-1})\right)q^{-b(n-k)}.
\end{equation}
Finally, for $0\leq u\leq n$,
\begin{equation}
\label{eq:transverse-nullity}
 \P(\dim\ker M\geq u)=O(q^{-b(u)}).
\end{equation}
\end{lemma}

\begin{lemma}[Split forms and their maximal isotropic subspaces]
\label{lem:transverse-split}
Let $r\geq1$. A nondegenerate symmetric form on a $2r$-dimensional
space over $\F_q$
has an $r$-dimensional totally isotropic subspace if and only if its
determinant character is $c_0=\chi((-1)^r)$. Such a form is a direct
orthogonal sum of $r$ hyperbolic planes. The total number of its
$r$-dimensional totally isotropic subspaces is
\begin{equation}
\label{eq:transverse-isotropic-count}
 N_r=\prod_{a=0}^{r-1}(1+q^a)
 =2q^{r(r-1)/2}(1+O(q^{-1})).
\end{equation}
The count includes both families of maximal isotropic subspaces.
\end{lemma}

\begin{lemma}[Concentration of restriction signs]
\label{lem:transverse-restrictions}
Let $\mathcal U$ be any nonempty family of distinct $r$-subspaces of
$\F_q^D$, with $r\geq1$, and let $Q$ be a uniform symmetric form.
For $\xi\in\{+1,-1\}$ put
\[
 f_\xi(Q)=\frac1{|\mathcal U|}\sum_{U\in\mathcal U}
 \1_{\{Q|_U\text{ nonsingular of sign }\xi\}}.
\]
Uniformly over the family $\mathcal U$,
\begin{equation}
\label{eq:transverse-restriction-error}
 \E\left|f_\xi(Q)-\frac12\right|
 =O\left(q^{-1/2}+|\mathcal U|^{-1/2}\right).
\end{equation}
The same bound holds after conditioning $Q$ to be nonsingular, or
conditioning both $Q$ and $Q-L$ to be nonsingular, uniformly over every
fixed symmetric form $L$.
\end{lemma}

\begin{lemma}[Complementary images]
\label{lem:transverse-projection}
Suppose $B\in\mathcal S_{2r}$ is nonsingular and $A\in\mathcal S_{2r}$
has rank $r$. Then
\begin{equation}
\label{eq:transverse-projection}
 \rank(B-A)=r\quad\Longleftrightarrow\quad AB^{-1}A=A.
\end{equation}
If $A$ and $A-B$ have discriminant signs $\xi_1,\xi_2$, respectively,
under these conditions, then
\begin{equation}
\label{eq:transverse-pair-sign}
 \chi(\det B)=c_0\xi_1\xi_2.
\end{equation}
\end{lemma}

\begin{lemma}[Local transverse approximation]
\label{lem:local-transverse}
Suppose $r>1$. For each face $j$, let $\mathcal T_j$ be the event that
all three differences between its point matrices are nonsingular.
Then, uniformly over the activity and sign choices,
\begin{equation}
\label{eq:transverse-local-l1}
 \E\bigl[\1_{\mathcal T_j}|F_j-G_j|\bigr]=O(q^{-1/2}).
\end{equation}
Moreover $0\leq F_j\leq C_D$ on $\mathcal T_j$, for a constant $C_D$
independent of $q$, and $0\leq G_j\leq8$ everywhere.
\end{lemma}

\begin{lemma}[Joint determinant signs]
\label{lem:joint-signs}
For fixed even $D\geq12$, the law of $(\eta_e^X)_{e\in E}$ converges
in total variation to that of independent uniform signs on
$\{+1,-1\}^E$.
\end{lemma}

\begin{proposition}
\label{prop:transverse-limit}
For every fixed even $D\geq12$, every activity pattern
$B\subseteq\mathscr C$, and every prescribed set of incidence signs,
\begin{equation}
\label{eq:transverse-limit}
 \E\left[\1_{\mathcal T}
       \prod_{(i,j)\in B}K_{\xi_{ij}}(X_i-Y_j)\right]
 =\E_\eta\prod_{j\in J}\prod_{\{i,k\}\subseteq A_j}
       (1+c_0\eta_{\{i,k\}}\xi_{ij}\xi_{kj})+o(1),
\end{equation}
where the $\eta_e$ are independent uniform signs. At each fixed $D$,
the error is uniform over all activity patterns and incidence signs.
\end{proposition}

\begin{corollary}\label{cor:threshold}
For a nontrivial increasing property of $r$-uniform hypergraphs on
$n\ge r$ vertices, where $r\ge3$, and every $0<\varepsilon<1/2$,
\[
 p_{1-\varepsilon}-p_\varepsilon
 \le\frac{2C_r}{(\log n)^{r/(r-1)}}
                  \log\frac{1-\varepsilon}{\varepsilon}.
\]
\end{corollary}

\begin{lemma}[Low-degree mass]\label{lem:low}
Let $m\ge2$ be real and let $h:\{0,1\}^J\to\{0,1\}$ satisfy
$I_i(h)\le I(h)/m$ for every $i\in J$. With
$k=\sigma\log m/64$, one has
\begin{equation}\label{eq:low}
 \sum_{1\le |S|\le k}\widehat h(S)^2\le m^{-1/4}I(h).
\end{equation}
The sum is empty when $k<1$.
\end{lemma}

\begin{theorem}\label{thm:main}
For every integer $r\ge3$ there is a finite constant $C_r$ such that,
for every integer $n\ge r$, every $0<p<1$, and every hypergraph property
$f:\{0,1\}^{E_{n,r}}\to\{0,1\}$,
\begin{equation}\label{eq:main}
 \Var_p(f)\le \frac{C_r}{(\log n)^{r/(r-1)}}I_p(f).
\end{equation}
No monotonicity assumption is required.
\end{theorem}

\begin{lemma}[Averaged restriction estimate]\label{lem:block}
Let $r+1\le m\le n$ be integers and set $k=\sigma\log m/64$.
For $B$ chosen uniformly among the $m$-subsets of $[n]$,
\begin{equation}\label{eq:block}
 \sum_{S\subseteq E}
 \Pr_B(1\le|S\cap F_B|\le k)\widehat f(S)^2
 \le m^{-1/4}\frac{rm}{n}I_p(f).
\end{equation}
\end{lemma}

\begin{lemma}[Capturing a support at one vertex]\label{lem:capture}
Let $n\ge r\ge3$ and $1\le m\le n$ be integers, let $k>0$, and put
\[
 \alpha=\frac r{r-1},\qquad L=(k/r)^\alpha.
\]
Suppose
\begin{equation}\label{eq:capture-condition}
 rL\frac{m-1}{n-1}\le\frac12.
\end{equation}
For a uniform $m$-subset $B$ of $[n]$ and every
$S\subseteq E_{n,r}$ with $1\le|S|\le L$,
\begin{equation}\label{eq:capture}
 \Pr_B(1\le|S\cap F_B|\le k)\ge\frac{m}{2n}.
\end{equation}
\end{lemma}

\begin{lemma}[Exact initialization]
\label{lem:initialization}
For every state of the enlarged binary state space and
\(0\leq j<H\),
\begin{equation}
 \frac12\leq\frac{f_{j+1}}{f_j}\leq 1.
 \label{eq:alg-adjacent}
\end{equation}
Consequently the ideal multiplier \(C(j)/c_{il}(j)\) changes by a
factor in \([1/2,2]\) between consecutive parameters, and
\(\mu_j\leq 2\mu_{j+1}\) pointwise.  Moreover,
\begin{equation}
 \min_{S\in\mathcal A}\mu_j(S)
 \geq 2^{-(H+p+K)}
 \qquad (0\leq j\leq H).
 \label{eq:alg-minimum-mass}
\end{equation}
The values \(C(0)\) and \(c_{il}(0)\), and hence all initial ideal
multipliers, are computable exactly in polynomial bit time.  The law
\(\mu_0\) has the following finite-choice description: independently
for each small cell \(s\), choose a uniform integer
\(k_s\in\{0,\ldots,b_s\}\), and then a uniform \(k_s\)-element subset
of its \(b_s\) labeled pairs to use their row elements.
\end{lemma}

\begin{proposition}[Accuracy of the reference experiment]
\label{prop:annealing}
With probability at least \(1-1/50\), the reference experiment does
not abort, every stored multiplier collection is good at its own
parameter in the sense of \eqref{eq:good-multipliers}, and
\begin{equation}
 \left|\log\frac{Z_{\rm ref}}{C(H)}\right|
 \leq 4H\eta.
 \label{eq:alg-reference-error}
\end{equation}
\end{proposition}

\begin{lemma}[Integer signature under balanced summation]
\label{lem:integer-signature}
Suppose \(M_t\ge1\) for every pair that is summed.
For every box-valid display \(z\) on the remaining coordinates with
\(\sum_i z_i=r+2\), the symmetric matrix
\begin{equation}
 \bigl(\Phi(z-e_i-e_h)\bigr)_{i,h}
 \quad\text{has at most one positive eigenvalue}.
 \label{eq:integer-removal-signature}
\end{equation}
The diagonal entries in this matrix are the weights after two
removals from the same coordinate; invalid removals have weight zero.
The corresponding assertion for two additions holds for every
box-valid display of total \(r-2\).
\end{lemma}

\begin{corollary}
\label{cor:hj-signatures}
For \(0\le j\le H\), the matrix of two-removal weights of \(h_j\)
at every box-valid display of total \(p+2\) has at most one positive
eigenvalue.
The corresponding two-addition matrix at every box-valid display
of total \(p-2\) has the same property.
\end{corollary}

\begin{lemma}[Log-concave tree marginals]
\label{lem:tree-marginal}
For integers \(v<k<w\) such that \(a_t(v),a_t(w)>0\),
\begin{equation}
 a_t(k)\ge
 a_t(v)^{(w-k)/(w-v)}
 a_t(w)^{(k-v)/(w-v)}.
 \label{eq:tree-marginal-interpolation}
\end{equation}
Consequently the positive support of \(a_t\) is an integer interval.
\end{lemma}

\begin{proposition}[Contamination bound]\label{prop:contamination}
For the feasible tightened instance,
\[
Z\le C(H)\le(1+\epsilon/32)Z.
\]
\end{proposition}

\begin{lemma}[Pair inequalities for defect masses]
\label{lem:defect-inequalities}
For every partial assignment \(\sigma\) and distinct unassigned
labels \(i,l\),
\begin{equation}
 4\widetilde c_{il}^{\sigma}\widetilde c_{li}^{\sigma}
 \le z_\sigma^2.
 \label{eq:defect-two-pair}
\end{equation}
For three distinct unassigned labels \(i,l,k\),
\begin{equation}
 \widetilde c_{il}^{\sigma}\widetilde c_{lk}^{\sigma}
 \le z_\sigma\widetilde c_{ik}^{\sigma}.
 \label{eq:defect-three-pair}
\end{equation}
\end{lemma}

\begin{proposition}
\label{prop:transversal-variance}
Suppose the multipliers satisfy~\eqref{eq:good-multipliers}.
For every real function $g$ on $\mathcal X$,
\begin{equation}
    C\Var_\mu(g)\leq C_{\mathrm p}\mathfrak D(g).
    \label{eq:transversal-variance}
\end{equation}
\end{proposition}

\begin{lemma}
\label{lem:defect-mean}
Suppose the multipliers satisfy~\eqref{eq:good-multipliers}, and let
$g$ be a real function on $\mathcal X$.
For each defect type $il$ there is a conditional transversal mean
$\bar g'$ such that
\begin{equation}
 (\bar g_{il}-\bar g')^2
       \leq \frac{C_{\mathrm d}}{C}\mathfrak D(g),
 \qquad
 (\bar g'-\mathbb E_\mu g)^2\leq4\Var_\mu(g).
 \label{eq:defect-mean-bounds}
\end{equation}
\end{lemma}

\begin{proposition}[Observable variance]
\label{prop:observable-variance}
Suppose the multipliers satisfy~\eqref{eq:good-multipliers}.
For every real $g$ on $\mathcal X$,
\begin{equation}
 \Var_\pi(\mathcal Qg)
 \leq(9C_{\mathrm p}+2C_{\mathrm d})\frac{\mathfrak D(g)}{C}
 \leq K_{\mathrm{obs}}\mathcal E(g).
 \label{eq:observable-variance}
\end{equation}
\end{proposition}

\begin{lemma}[Time averages from a dominated initial law]
\label{lem:time-average}
Suppose the multipliers satisfy~\eqref{eq:good-multipliers}.
Let $G$ be a real function on $\mathcal X$ with $\mathcal QG=G$.
Suppose $S_0$ has law $\nu$ satisfying $\nu(S)\leq U\pi(S)$ for
every state. For $N\geq1$ consecutive observations of the chain,
\begin{equation}
 \mathbb E_\nu\left[
    \left(\frac1N\sum_{t=0}^{N-1}G(S_t)-\mathbb E_\pi G\right)^2
                  \right]
 \leq\frac{2UK_{\mathrm{obs}}}{N}\Var_\pi(G).
 \label{eq:time-average-bound}
\end{equation}
\end{lemma}

\begin{lemma}[Trace mixing and return cost]
\label{lem:trace}
Suppose the multipliers satisfy~\eqref{eq:good-multipliers}.
The trace kernel $P_{\mathrm{tr}}$ is irreducible, reversible with
stationary law $\mu$, and has holding probability at least $1/2$.
Its inverse spectral gap is at most
$2p^2C_{\mathrm p}\leq K_{\mathrm{obs}}$.
In particular, with
$\mu_{\min}=\min_{x\in\mathcal A}\mu(x)>0$, for every integer $s\geq0$,
\begin{equation}
 \left|\frac{P_{\mathrm{tr}}^s(x,y)}{\mu(y)}-1\right|
 \leq\mu_{\min}^{-1}\exp(-s/K_{\mathrm{obs}})
 \qquad(x,y\in\mathcal A).
 \label{eq:trace-relative-mixing}
\end{equation}
If the initial trace law satisfies $\nu\leq U\mu$ pointwise, then
\begin{equation}
  \mathbb E_\nu T_{\mathcal A}^+
       \leq\frac{U}{\pi(\mathcal A)}.
  \label{eq:trace-return-cost}
\end{equation}
Furthermore, at every deterministic trace-step index the law remains
bounded by $U\mu$. The expected total number of underlying
transitions for $s$ trace steps is at most $sU/\pi(\mathcal A)$.
\end{lemma}

\begin{lemma}
\label{lem:counting-lifts}
If $k$ has both integer signatures of Definition~\ref{def:integer-signatures},
then $f$ has the omission property and $\widetilde f$ has the addition
property.  Both properties persist under fixing included or excluded
elements and summing disjoint labelled pairs at occupancy one, on each
resulting full valid-degree domain.  Moreover, with $q=(p+1)^2$,
\begin{equation}
 q^{-1}f(S)\leq\widetilde f(S)\leq qf(S)
 \quad\left(S\in\mathcal A\cup\bigcup_{i\ne l}\mathcal A_{il}\right).
 \label{eq:counting-comparison}
\end{equation}
\end{lemma}

\begin{proposition}[Companion transport and simulation input]
\label{prop:counting-transport}
Suppose $f$ is positive on all $p$-subsets and has the omission property,
$\widetilde f$ is positive on that domain and has the addition property,
the weights agree on $\mathcal A$, and
\eqref{eq:counting-comparison} holds with $q\geq1$.
For good multipliers put
\begin{equation}
 C_{\rm p}=p(1+8pq^2),\qquad
 C_{\rm d}=8+32pq^3,\qquad
 K_{\rm obs}=10p^4(9C_{\rm p}+2C_{\rm d}).
 \label{eq:counting-constants}
\end{equation}
Then for every real function $g$ on $\mathcal X$,
\begin{equation}
 C\operatorname{Var}_\mu(g)\leq C_{\rm p}\mathfrak D(g),\qquad
 \operatorname{Var}_\pi(\mathcal Qg)
 \leq(9C_{\rm p}+2C_{\rm d})\frac{\mathfrak D(g)}C
 \leq K_{\rm obs}\mathcal E_P(g).
 \label{eq:counting-variance}
\end{equation}
If $\mathcal QG=G$ and an initial law satisfies $\nu\leq D\pi$
pointwise, then $m\geq1$ consecutive observations satisfy
\begin{equation}
 \mathbb E_\nu\left[
  \left(m^{-1}\sum_{t=0}^{m-1}G(S_t)-\mathbb E_\pi G\right)^2\right]
 \leq\frac{2D K_{\rm obs}}m\operatorname{Var}_\pi(G).
 \label{eq:counting-time-average}
\end{equation}
The trace on $\mathcal A$, counting every strictly positive return as
one step, is lazy and reversible with stationary law $\mu$ and inverse
spectral gap at most $2p^2C_{\rm p}\leq K_{\rm obs}$.  In particular,
\begin{equation}
 \left|\frac{P_{\rm tr}^t(x,y)}{\mu(y)}-1\right|
 \leq\mu_{\min}^{-1}\exp(-t/K_{\rm obs}).
 \label{eq:counting-trace-mixing}
\end{equation}
If a trace starts from $\nu\leq D\mu$, the expected cost of $t$ trace
steps in underlying transitions is at most $tD/\pi(\mathcal A)$;
at each deterministic trace index its law is still at most $D\mu$.
\end{proposition}

\begin{lemma}[Initialization and adjacent phases]
\label{lem:counting-initialization}
For every $p$-subset and $0\leq j<H_o$,
\begin{equation}
 \frac12\leq\frac{f_{j+1}(S)}{f_j(S)}\leq1.
 \label{eq:counting-adjacent}
\end{equation}
Thus $C_j/c_{il}(j)$ changes by a factor in $[1/2,2]$ between
consecutive phases, and $\mu_j=f_j/C_j$ on $\mathcal A$ satisfies
$\mu_j\leq2\mu_{j+1}$.  Moreover
\begin{equation}
 \min_{S\in\mathcal A}\mu_j(S)
       \geq2^{-(H_o+p+K_o)}.
 \label{eq:counting-minimum}
\end{equation}
The initial masses are exact rational numbers computable in polynomial
bit time, and $\mu_0$ can be sampled by independent uniform port counts
followed by uniform subsets of the pairs realizing those counts.
\end{lemma}

\begin{proposition}
\label{prop:counting-reference}
With probability at least $1-1/50$, this experiment does not abort,
every stored multiplier collection is good at its own phase, and
\begin{equation}
 \left|\log\frac{Y_{\rm ref}}{C_{H_o}}\right|\leq4H_o\eta.
 \label{eq:counting-reference-error}
\end{equation}
\end{proposition}

\begin{lemma}
\label{lem:counting-bits}
The implemented experiment has deterministic polynomial bounds on
oracle calls, bit operations, and output length, on every execution.
It can be coupled to the capped reference experiment so that, except
with probability at most $20J_*\xi$, all states, type counts,
multiplier updates, and cap decisions coincide, every weight evaluation
meets its tolerance, and each positive observed ratio differs from
its reference value by log error at most $4\xi$.
\end{lemma}

\begin{lemma}[Integral and point-weight bounds]\label{lem:weight-bounds}
For every block and every port argument in its box,
\begin{equation}\label{eq:integral-bounds}
 e^{-N^{50000}}\le\widetilde I_G(u)\le e^K.
\end{equation}
For the weight $h$ on the full paired slice of
Proposition~\ref{prop:port-model},
\begin{equation}\label{eq:weight-log-bound}
 |\log h(a,b)|\le N^{60000}.
\end{equation}
All rational coefficients needed to define or evaluate its factors
have polynomial encoding length in the input and in the query.
\end{lemma}

\begin{lemma}[Accuracy and guarantees for the volume lift]
\label{lem:volume-lift}
The polytope~\eqref{eq:volume-lift} has dimension $f+6m+d_0$, a
polynomial facet-encoding bound, and an exact polynomial-time strong
separation oracle. It contains a known rational ball of radius $1/32$
and has an outer ball of polynomial encoding length. Furthermore,
\begin{equation}\label{eq:volume-lift-accuracy}
 (1-\rho/10)\widetilde I_G(u)
       \le\vol(\mathcal Q)\le\widetilde I_G(u).
\end{equation}
All polynomial bounds are in the original input length, the encoding
lengths of $u$ and $\rho$, $N$, and $\rho^{-1}$, with absolute fixed exponents.
\end{lemma}

\begin{lemma}[Computable partitions and compatible orders]
\label{lem:partitions}
Each part of \(\mathcal D_i\) is contained in a superblock.
The three partitions can be found with polynomially many oracle calls
and bit operations.  Each has a generating family of at most \(n^2\)
sets satisfying its defining strict slack bound.

Fix a superblock order \(G_1,\ldots,G_g\) supplied by
Lemma~\ref{lem:generator-prefixes} for the \(s_*\)-generators.
Every prefix \(F_k=G_1\cup\cdots\cup G_k\), including the empty
and full prefixes, satisfies
\begin{equation}\label{eq:superblock-prefix-slack}
 s_*(F_k)\le N^4S.
\end{equation}
For system 1 use this order, and for system 2 use its reverse.  The
sets preceding a superblock \(G_k\) in these orders are therefore
\begin{equation}\label{eq:superblock-prefixes}
 A_{1G_k}=F_{k-1},\qquad A_{2G_k}=E\setminus F_k.
\end{equation}
\end{lemma}

\begin{lemma}[Shift averages]\label{lem:shift-average}
For \(F=Y\) and for \(F=Y^+\), every integral full or restricted
star shift with \(|l_j|\le S/N^{25}\) satisfies
\begin{equation}\label{eq:small-shift-ratio}
 e^{-N^{-8}}\le \frac{F(d(l))}{F(0)}\le e^{N^{-8}}.
\end{equation}
For \((\kappa,A_\kappa)=(\omega,A_\omega)\) or \((\psi,J)\),
on its corresponding star lattice,
\begin{equation}\label{eq:average-comparison}
 e^{-3N^{-8}}F(0)
 \le \frac{1}{A_\kappa}\sum_l\kappa(l)F(d(l))
 \le e^{3N^{-8}}F(0).
\end{equation}
The lower bound remains valid if the sum is restricted to
\(\max_j|l_j|\le S/N^{25}\).
\end{lemma}

\begin{proposition}[Expansion costs little]\label{prop:expansion}
The expanded common-base count satisfies
\begin{equation}\label{eq:expansion-comparison}
 Z\le Z^+\le e^{20N^{-8}}Z.
\end{equation}
\end{proposition}

\begin{lemma}[The expansion matroid]\label{lem:expansion-matroid}
Let $r:2^E\to\mathbb Z_{\geq0}$ be normalized, nondecreasing, and
submodular.  Replace each $j\in E$ by any finite number of labelled
copies.  Declare a set of copies independent when its occupancy vector
$z$ satisfies $z(A)\leq r(A)$ for every $A\subseteq E$.
This defines a matroid.  A set of copies with occupancy vector $v$ has
matroid rank
\begin{equation}\label{eq:expansion-rank}
 m(v)=\min_{A\subseteq E}\{r(A)+v(E\setminus A)\}.
\end{equation}
\end{lemma}

\begin{lemma}[A center for affine slacks]\label{lem:center}
Let $Q\subseteq\mathbb R^n$ be a nonempty bounded rational polytope
satisfying the hypotheses of Proposition~\ref{prop:oracle-tools}.
One can find a rational $c\in Q$, with polynomial encoding length,
such that every affine $F$ nonnegative on $Q$ satisfies
\begin{equation}\label{eq:center-slack}
 \max_{x\in Q}F(x)\leq4(n+1)F(c).
\end{equation}
The construction has polynomial oracle and bit complexity.
It also returns an affinely spanning vertex simplex of $Q$ such that
every point of $Q$ has all barycentric coordinates of absolute value
at most two with respect to that simplex.
\end{lemma}

\begin{lemma}[Derivatives after smoothing]\label{lem:smooth-derivatives}
In block count coordinates, $g=\log\widetilde I_G$ is $C^3$, is concave,
and satisfies, everywhere,
\begin{equation}\label{eq:smooth-derivative-bounds}
 |g''_{ij}|\le A_2=N^{800}/W^2,\qquad
 |g'''_{ijk}|\le A_3=N^{1250}/W^3.
\end{equation}
\end{lemma}

\begin{lemma}[Block signatures at every power]\label{lem:block-signatures}
For $0\le s\le1$, every block factor $F_G^s$ has both normalized
positive-semidefinite tests of~\eqref{eq:signature-normalization}:
$\one\one^{\mathsf T}-Q\succeq0$, for additions and removals.
\end{lemma}

\begin{lemma}\label{lem:coefficient}
For distinct unassigned indices $i,j$,
\begin{equation}\label{eq:coefficientpair}
 4c^{\sigma}_{ij}c^{\sigma}_{ji}\le z_{\sigma}^2.
\end{equation}
For distinct unassigned indices $i,j,k$,
\begin{equation}\label{eq:coefficient}
 c^{\sigma}_{ij}c^{\sigma}_{jk}\le z_{\sigma}c^{\sigma}_{ik}.
\end{equation}
\end{lemma}

\begin{lemma}[Transport]\label{lem:transport}
With the notation above,
\begin{equation}\label{eq:transport}
 (\overline H_p-\overline H_d)^2
 \le
 \left(\frac1{s_pW_p}+\frac1{s_dW_d}
       +\frac2{s_ps_d}\sum_{t=1}^m\frac{v_t}{W_t}\right)
 D_{\mathcal X}(H).
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:transversalvariance}
For good multipliers and every $H:\Om\to\R$,
\begin{equation}\label{eq:transversalvariance}
 \Var_\mu H\le C_{\rm p}\frac{D(H)}{c_0},
 \qquad C_{\rm p}=n(1+8n).
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:defecttransfer}
Assume the multipliers are good, and let $H:\Om\to\R$.
For each defect type $ij$ there is an event $\mathcal A\subseteq\Om_0$
obtained by prescribing the selected elements in pairs $i,j$, with
$\mu(\mathcal A)\ge1/4$.  Its conditional mean
$\overline H'=\E_\mu[H\mid\mathcal A]$ satisfies
\begin{equation}\label{eq:defecttransfer}
 (\overline H_{ij}-\overline H')^2
       \le C_{\rm d}\frac{D(H)}{c_0},
 \qquad C_{\rm d}=8+32n,
\end{equation}
and
\begin{equation}\label{eq:conditionalmean}
 (\overline H'-\overline H_0)^2\le4\Var_\mu H.
\end{equation}
\end{lemma}

\begin{proposition}[Observable Poincar\'e inequality]\label{prop:observable}
For good multipliers and every $H:\Om\to\R$,
\begin{equation}\label{eq:observable}
 \Var_\pi(\Qproj H)\le K_{\rm obs}\calE(H),
 \qquad K_{\rm obs}=2000n^6.
\end{equation}
\end{proposition}

\begin{lemma}\label{lem:timeaverages}
Suppose the multipliers are good.  If $G=\Qproj G$ and a trajectory
$(X_t)$ of $P$ starts with law $\nu\le U\pi$, then for every integer
$N\ge1$,
\begin{equation}\label{eq:MSE}
 \E_\nu\left[\left(\frac1N\sum_{t=0}^{N-1}G(X_t)-\E_\pi G\right)^2\right]
 \le\frac{2UK_{\rm obs}\Var_\pi G}{N}.
\end{equation}
\end{lemma}

\begin{lemma}\label{lem:trace}
With good multipliers, $P_A$ is reversible with stationary law $\mu$,
irreducible, and lazy.  Its inverse spectral gap is at most $18n^4$.
In particular, for every integer $s\ge0$,
\begin{equation}\label{eq:tracemixing}
 \left|\frac{P_A^s(x,y)}{\mu(y)}-1\right|
 \le\frac{\exp(-s/(18n^4))}{\min_{z\in A}\mu(z)}
 \quad(x,y\in A).
\end{equation}
If a trace step begins with a law $\nu\le U\mu$, its expected number of
underlying transitions is at most
\begin{equation}\label{eq:returncost}
 \frac{U}{\pi(A)}\le5Un^2.
\end{equation}
\end{lemma}

\begin{proposition}[Small-chain bound]\label{prop:small-chain}
The kernel $P$ is lazy and reversible for $\pi(X)=f(X)/\Lambda$. On every
edge it satisfies
\[
 P(X,Y)\ge \frac{1}{128d^2}
                  \min\left\{1,\frac{f(Y)}{f(X)}\right\}.
\]
If there is more than one state, its inverse spectral gap is at most
$d^{160}$. Moreover
$\pi_{\min}\ge(C+1)^{-2d}$, and, for every $t\ge0$,
\begin{equation}\label{eq:small-mixing}
 \TV\bigl(P^t(X_0,\cdot),\pi\bigr)
 \le (C+1)^{2d}\exp(-t/d^{160}).
\end{equation}
A one-state chain is already stationary.
\end{proposition}

\begin{theorem}[Exact sampling]\label{thm:exact-sampling}
There is an algorithm using unbiased random bits that terminates almost
surely, outputs an exactly uniform element of $\Omega$, and has expected
bit running time polynomial in $d,b$.
\end{theorem}

\begin{proposition}[Bin rejection]\label{prop:bin-acceptance}
An ideal trial succeeds with probability at least $1/64$.  Conditional on
success, its output is exactly uniform on the feasible integer tables.
\end{proposition}

\begin{lemma}[Finite-box integral interpolation]\label{lem:integral-interpolation}
Let $S_1,S_2,S_0$ be bounded finite unions of open axis-aligned boxes in
$\R^q$, and let $0<t<1$, with
$(1-t)S_1+tS_2\subset S_0$.  Let $f_1,f_2,f_0$ be positive continuous
functions on a compact box containing the closures of these sets.
If
\[
 f_0((1-t)x+ty)\ge f_1(x)^{1-t}f_2(y)^t
 \quad(x\in S_1,\ y\in S_2),
\]
then
\begin{equation}\label{eq:integral-interpolation}
 \int_{S_0}f_0\ge
       \left(\int_{S_1}f_1\right)^{1-t}
       \left(\int_{S_2}f_2\right)^t.
\end{equation}
In particular, for finite unions $S,D_0$ of open boxes in the sampling
cube,
\begin{equation}\label{eq:dense-logconcave-interpolation}
 \int_{(1-t)S+tD_0}\rho\ge
       \left(\int_S\rho\right)^{1-t}
       \left(\int_{D_0}\rho\right)^t.
\end{equation}
\end{lemma}

\begin{proposition}[Stationary mass and unpadding]\label{prop:stationary-success}
The masses satisfy
\begin{equation}\label{eq:stationary-mass-bounds}
 0<Z_0\le\Lambda\le(1+d^2)Z_0,
 \qquad \pi_{\min}\ge(C+1)^{-2d}.
\end{equation}
Draw $X$ with law $\pi$ and then a uniform $A\in\mathcal F_X$.
Declare success if $X$ is a transversal and every large entry of $A$
is at least $L$.  Subtracting $L$ from these entries gives a uniform
original table conditional on success, and
\begin{equation}\label{eq:unpadding-success}
 \Pp\{\text{success}\}\ge\frac{1}{2(1+d^2)}.
\end{equation}
\end{proposition}

\begin{lemma}[Laminar factors]\label{lem:laminar-signature}
With no balanced slots summed, every two-removal matrix just defined has
at most one positive eigenvalue.
\end{lemma}

\begin{lemma}[Pair summation]\label{lem:pair-summation}
Fix a box-valid display $p$ on the old active coordinates, a fresh slot
of capacity $B\ge2$, and fixed context and balanced sums as above.
Choose its displayed occupancy $D'\in\{B,B+1\}$ so that
\begin{equation}\label{eq:pair-total}
 c+|p|+D'+\sum_{s\in\mathcal R}B_s=T+2.
\end{equation}
Write $\Phi(r,a,b)$ for the weight after the balanced sums, with old
values $r$ and fresh pair $(a,b)$.  The box-valid displays
$(p,j,D'-j)$ are indexed by
\[
 \mathcal J=
 \begin{cases}
 \{0,\ldots,D'\},&D'=B,\\
 \{1,\ldots,D'-1\},&D'=B+1.
 \end{cases}
\]
Their two-removal matrices have the blocks
\begin{align*}
 (V_j)_{ih}&=\Phi(p-e_i-e_h,j,D'-j),\\
 S(l)_i&=\Phi(p-e_i,l,D'-1-l),\\
 u_j&=\Phi(p,j-1,D'-1-j).
\end{align*}
Thus $V_j$ records two old removals, $S(l)$ one old and one fresh
removal, and $u_j$ one removal from each fresh coordinate of display
$j$.  Put $S(l)=0$ outside
$0\le l\le D'-1$ and $u_j=0$ outside $1\le j\le D'-1$.
Suppose each matrix
\begin{equation}\label{eq:pair-block}
 M_j=\begin{pmatrix}
 V_j&S(j-1)&S(j)\\
 S(j-1)^{\mathsf T}&u_{j-1}&u_j\\
 S(j)^{\mathsf T}&u_j&u_{j+1}
 \end{pmatrix},\qquad j\in\mathcal J,
\end{equation}
has at most one positive eigenvalue.  The entries $u_{j-1}$ and
$u_{j+1}$ are the double removals at the first and second fresh
coordinates, respectively.
For every real old vector $h$ satisfying
$\sum_{l=0}^{D'-1}h^{\mathsf T}S(l)=0$, define
\begin{equation}\label{eq:pair-cumulative}
 g_j=\frac{\sum_{l=0}^{j-1}h^{\mathsf T}S(l)}{u_j}
       \quad(1\le j\le D'-1),\qquad
 g_j=0\quad\text{otherwise}.
\end{equation}
All these divisions are valid, and
\begin{equation}\label{eq:pair-one}
 -h^{\mathsf T}V_jh\ \ge\
 2u_jg_j^2-u_{j-1}g_{j-1}^2-u_{j+1}g_{j+1}^2,
 \qquad j\in\mathcal J.
\end{equation}
If $D'=B$, the matrix $\sum_{j=0}^B V_j$ has at most one positive
eigenvalue.
If $D'=B+1$, then
\begin{equation}\label{eq:pair-weighted}
 2\sum_{j=1}^{D'-1}u_jg_j^2
 \ \le\
 -h^{\mathsf T}\left(\sum_{j=1}^{D'-1}j(D'-j)V_j\right)h.
\end{equation}
\end{lemma}

\begin{lemma}[Child log-concavity]\label{lem:child-logconcavity}
At every context with positive transversal mass, the child masses
$(z_j)_{j=0}^U$ are log-concave and their positive support is an integer
interval.  If $z_a,z_b>0$ and $a\le j\le b$, then
$z_j\ge\min(z_a,z_b)$.
\end{lemma}

\begin{lemma}[Conditional transport]\label{lem:transport}
Let $\sigma$ be a row-major context, and let children $l-1,l$ of its
next slot have positive masses $z_-,z_+$ and means $H_-,H_+$.  Then
\begin{equation}\label{eq:conditional-transport}
 \min(z_-,z_+)(H_--H_+)^2
 \le A_0 E_\sigma(H),\qquad A_0=2+2d(U+1)^2.
\end{equation}
\end{lemma}

\begin{theorem}[Graph Poincar\'e inequality]\label{thm:poincare}
For every real function $H$ on the feasible small graph,
\begin{equation}\label{eq:graph-poincare}
 \Lambda\Var_{f/\Lambda}H
 \le \left((1+2d^2)4d^2(U+1)^6+2\right)E(H)
 \le 770d^4U^6 E(H).
\end{equation}
In particular, the feasible graph is connected.
\end{theorem}

\begin{corollary}\label{cor:typical-cover}
Let $n\geq2$, let $H$ have an edge and at most $n$ vertices,
and suppose $q(H;n)<r<1$. If a family of graphs on $[n]$
satisfies $\mu_r(\calD)\geq1-1/K_0$, then some copy of $H$
has its edges contained in the union of $K_0$ members of $\calD$.
\end{corollary}

\begin{lemma}\label{lem:q-lower}
If $H$ has an edge, $|V(H)|\leq n$, and $d=\degen(H)$, then
\begin{equation}\label{eq:q-lower}
 q(H;n)\geq\frac1{2\binom n2},\qquad
 q(H;n)\geq\frac12 n^{-2/d}.
\end{equation}
\end{lemma}

\begin{lemma}[Degeneracy splitting]\label{lem:split}
For every positive integer $m$, the edges of a $d$-degenerate
graph can be partitioned into $m$ graphs, each of degeneracy
at most $\lceil d/m\rceil$.
\end{lemma}

\begin{lemma}[Compression after a random extension]
\label{lem:compression}
Let $Y$ be finite, $r\in(0,1)$, and $s\geq1$ an integer.
For every nonempty family
\[
 \calR\subseteq\{T\subseteq Y:1\leq|T|\leq s\}
\]
there is a nonempty subfamily $\calQ\subseteq\calR$ with
$|\calQ|\leq\lceil2r^{-s}\rceil$ such that
\begin{equation}\label{eq:compression}
 S\text{ satisfies }\calR\quad\Longrightarrow\quad
 f_{\calQ}(S)\geq1/2.
\end{equation}
\end{lemma}

\begin{proposition}[Neighborhood transfer]\label{prop:transfer}
There is an absolute integer $N_1$ such that the following holds
for every $n\geq N_1$ and every $r,s$ satisfying
\eqref{eq:parameters}. There exists
$\calD=\calD(n,r,s)\subseteq2^{E(K_n)}$ with
$\mu_r(\calD)\geq1-1/K_0$ such that, whenever
\begin{itemize}
\item $Y\subseteq[n]$ has $|Y|\leq n^{2/3}$;
\item $J$ is a labelled bipartite graph with all edges between
      $Y$ and $[n]\setminus Y$, and $E(J)\subseteq E(G)$
      for some $G\in\calD$;
\item at most $n/8$ vertices outside $Y$ have positive degree in
      $J$, and all of those degrees are at most $s$;
\end{itemize}
one has
\begin{equation}\label{eq:transfer}
 p_c(J;n)\leq r_*:=1-(1-r)^{32}\leq32r.
\end{equation}
\end{proposition}

\begin{proposition}\label{prop:degree-embedding}
There is an absolute integer $N_2$ such that, for $n\geq N_2$
and $r,s$ satisfying \eqref{eq:parameters}, every graph $J$
with
\[
 |V_+(J)|\leq n/4,\qquad \degen(J)\leq s,
 \qquad\Delta(J)\leq n^{2/3}
\]
and at most $n$ vertices satisfies $p_c(J;n)\leq r$.
\end{proposition}

\begin{proposition}\label{prop:stars}
Put $A=400e^4$. There is an absolute integer $N_3$ such that,
for every $n\geq N_3$ and every star forest $J$ on at most $n$
vertices with $|V_+(J)|\leq n/100$,
\begin{equation}\label{eq:star-threshold}
 p_c(J;n)\leq2Aq(J;n).
\end{equation}
If $q(J;n)<1/(2A)$, the stronger bound
$p_c(J;n)\leq Aq(J;n)$ holds.
\end{proposition}

\begin{theorem}[Multiscale selector estimate]
\label{thm:multiscale-selector}
Let $X$ be a finite set, let $\F$ be a nonempty family of nonempty
subsets of $X$, and suppose that $\F$ is not $p$-small, where
$0<p\le 1$.  For each $H\in\F$, let $\lambda_H$ be a probability mass
function on $X$ supported on $H$.  Set $D=256$, and let $s\ge 0$ be an
integer such that
\[
  p\sum_{i=1}^s D^i\le \frac12.
\]
Independently color the elements of $X$ by a map
$a:X\to\{1,\ldots,s+1\}$, with color probabilities
\begin{equation}
\label{sel:color-probabilities}
  \pi_i=D^ip\quad(1\le i\le s),
  \qquad
  \pi_{s+1}=1-p\sum_{i=1}^sD^i.
\end{equation}
For a coloring $v$, write $A_i(v)=\{x\in X:v(x)\le i\}$.
With probability at least $9/10$, there is an $H\in\F$ such that
\begin{equation}
\label{sel:simultaneous-capture}
  \lambda_H(A_i(a))\ge 1-2^{-i}
  \qquad(1\le i\le s).
\end{equation}
In particular, with probability at least $9/10$, there is an
$H\in\F$ for which
\begin{equation}
\label{sel:average-color}
  \sum_{x\in X}a(x)\lambda_H(x)\le 2.
\end{equation}
\end{theorem}

\begin{lemma}[Maximal truncation]
\label{sel:truncation}
Let $\lambda$ be a probability mass function on a finite set $X$,
let $A\subseteq X$, and let $m\ge 0$ and $0<d<1$.
Call $u\in[0,1]$ admissible if
\begin{equation}
\label{sel:admissible-cutoff}
  \{x:\lambda(x)>u\}\subseteq A,
  \qquad
  \sum_{x\in X}\min\{\lambda(x),u\}
       \bigl(\mathbf 1_A(x)-(1-d)\bigr)\ge mu.
\end{equation}
If there is an admissible cutoff, there is a largest one,
$\varepsilon$, and it satisfies
\[
  |\{x:\lambda(x)>\varepsilon\}|\le \frac{m}{d}.
\]
\end{lemma}

\begin{lemma}[Conditioning and extensions]\label{lem:channel-conditioning}
For a channel $Y$, both identities in \eqref{eq:channel-laws} hold with
conditioning on its maximal measure-distal factor $W_Y$ in place of
$V$.  Every flow extension of $Y$ over $C$ is a channel with the pulled
back output data, and the same strengthening holds there.
\end{lemma}

\begin{proposition}[Channel closure]\label{prop:channel-closure}
Let $Y$ be a channel and $b\in I$.  On $\mathsf M_b(Y)$ take
$\pi_Y(y_b)$ as original factor and take every $D_\gamma(y_i)$,
$i\in I$, as an output, in the old group of $\gamma$.
These data make $\mathsf M_b(Y)$ a channel.
\end{proposition}

\begin{corollary}\label{cor:channel-copied-law}
For every channel $Y$, the copied spatial list
$(d_Y(y_i))_{i\in I}$ under $\lambda_Y$ has its full product law
conditional on $P=(\omega_Y(y_i))_{i\in I}$.
\end{corollary}

\begin{lemma}[Simultaneous saturation]
\label{lem:saturation}
Every standard flow $Y$ over $C$ has a standard flow extension $Y_*\to Y$
over $C$ with the following property. For every further standard flow
extension $\rho:Y'\to Y_*$ over $C$, every $f\in L^2(\lambda_{Y_*})$,
and every $l\in\{0\}\cup I$,
\begin{equation}
 \E_{\lambda_{Y'}}[f\circ\rho^I\mid\mathcal D_l(Y')]
 =\E_{\lambda_{Y_*}}[f\mid\mathcal D_l(Y_*)]\circ\rho^I.
 \label{eq:saturation}
\end{equation}
\end{lemma}

\begin{lemma}[The regrouped channel]
\label{lem:regrouped-channel}
The preceding output lists and groups make $Z$ a channel over its
original factor $\pi_Y(y_b)$.
\end{lemma}

\begin{lemma}[Relative norm convergence]\label{lem:relative-norm}
Suppose $Y\to B$ is relatively weakly mixing for $R$. For distinct
nonzero integers $a_1,\ldots,a_d$ and bounded $G_1,\ldots,G_d$,
\begin{equation}\label{eq:relative-norm}
 \left\|\frac1N\sum_{l=1}^N
 \left(\prod_{i=1}^dG_i\circ R^{a_il}
       -\prod_{i=1}^d\E[G_i\mid B]\circ R^{a_il}\right)\right\|_2
 \longrightarrow0.
\end{equation}
\end{lemma}

\begin{lemma}[Triple pointwise convergence]\label{lem:triple-convergence}
On any standard invertible probability-preserving system, averages
of at most three bounded functions at distinct positive integer
slopes converge almost everywhere along all positive integer lengths.
\end{lemma}

\begin{lemma}[Gaussian matrix estimate]\label{lem:packing-gaussian}
Let $B_1,\ldots,B_r$ be matrices between two finite-dimensional real
Hilbert spaces, and put
\[
 H_j=\begin{pmatrix}0&B_j\\B_j^*&0\end{pmatrix},
 \qquad S=\sum_{j=1}^rH_j^2.
\]
If $\norm{S}_{\rm op}\le\sqrt d$ and $\tr S\le2d$ for some
$d\ge1$, then for independent standard normal variables $g_j$,
\begin{equation}\label{eq:packing-gaussian-bound}
 \E\left\|\sum_{j=1}^rg_jB_j\right\|_{\rm op}
       \le C d^{1/4}\sqrt{\log(2+d)}.
\end{equation}
The constant is independent of the dimensions of the two spaces.
\end{lemma}

\begin{lemma}[Selected positive witness]\label{lem:selected-witness}
There are a finite set $F\subseteq[1,2]$ containing $1$ and measurable
functions $N_a:C\to[2^a,\infty)$, $a\in\N$, independent of the phase,
with
\begin{equation}\label{eq:selector-grid}
  N_a(x,u)\in\{c2^k:c\in F,\ k\ge a\},\qquad
  N_a(x,u)=2^a\quad(x\notin E_*),
\end{equation}
such that $B_{\lfloor N_a(x,u)\rfloor}(x)>\delta$ on $E_*$.
Moreover, there is a continuous nonnegative function $\Psi$ on
$(\R/\Z)^I$ for which
\begin{equation}\label{eq:selected-positive-limit}
 \liminf_{a\to\infty}\int_C\frac1{N_a(z)}
 \int_0^{N_a(z)}
 \Psi\bigl((\upsilon(S_C^{it}z))_{i\in I}\bigr)
 \prod_{i\in J_0}f_i\bigl(\xi(S_C^{it}z)\bigr)
 \,\dd t\,\dd m_C(z)>0.
\end{equation}
\end{lemma}

\begin{proposition}[Parameter and small-marginal laws]
\label{prop:selected-parameters}
For every flow $Y$ over $C$ and bounded measurable $H_i$ on $W_Y$,
\begin{equation}\label{eq:deterministic-parameters}
 \E_{\lambda_Y}\prod_{i\in I}H_i(P_i)
 =\lim_{L\to\infty}\int_Y\frac1L\int_0^L
   \prod_{i\in I}H_i\bigl(\omega_Y(S_Y^{it}y)\bigr)
   \,\dd t\,\dd m_Y(y).
\end{equation}
For every nonempty $J\subseteq I$ with $\abs{J}\le3$,
\begin{equation}\label{eq:small-conditional-law}
 \law_{\lambda_Y}\bigl((y_i)_{i\in J}\mid P\bigr)
   =\bigotimes_{i\in J}m_{Y,P_i}.
\end{equation}
\end{proposition}

\begin{lemma}[Normalized joining flow]\label{lem:normalized-joining}
For $b\in I$, define
\begin{equation}\label{eq:normalized-joining}
 \mathsf M_b(Y)=
 \left(Y^I,\lambda_Y,
   S_{\mathsf M_b(Y)}^t(y_i)_i=(S_Y^{it/b}y_i)_i\right).
\end{equation}
This is a standard probability-preserving flow over $C$ via
$(y_i)_i\mapsto\pi_Y(y_b)$, and projection onto slot $b$ is an
extension onto $Y$.  The array $P$ belongs to the maximal
measure-distal factor of $\mathsf M_b(Y)$ for time one.
\end{lemma}

\begin{lemma}[The retained positive correlation]\label{lem:positive-witness}
With the functions and phase test of Lemma~\ref{lem:selected-witness},
\begin{equation}\label{eq:positive-witness}
 \int_{C^I}\Psi\bigl((\upsilon(z_i))_i\bigr)
    \prod_{i\in J_0}f_i\bigl(\xi(z_i)\bigr)\,\dd\lambda_C>0.
\end{equation}
The phase array in this integral is measurable in the distal
parameter array of $C^I$.
\end{lemma}

\begin{lemma}[The row--column identity]
\label{lem:row-column}
Under $\lambda_Z$,
\begin{equation}
 \E\big[q((y_i)_i)q(\mathbf z_b)\mid E\big]
   =\int_Y g(p,y)u(E_b,y)\,\dd m_{Y,w}(y).
 \label{eq:row-column}
\end{equation}
Moreover, in a single $Z$-state with law $m_Z$, the conditional law
of its slot-$b$ state given $e$ is $m_{Y,\kappa(e)}$.
\end{lemma}

\begin{lemma}[Parameter independence]
\label{lem:parameter-independence}
Under $\lambda_Z$, the random variables $p$ and $E_b$ are
conditionally independent given $w$.
\end{lemma}

\begin{lemma}[A relatively weakly mixing characteristic factor]
\label{lem:relative-norm}
Suppose $Y\to B$ is relatively weakly mixing for an invertible
transformation $R$.  If $a_1,\ldots,a_d$ are distinct nonzero integers
and $g_1,\ldots,g_d$ are bounded, then
\begin{equation}\label{eq:relative-norm}
 \left\|\frac1N\sum_{n=1}^N
 \left(\prod_{i=1}^d g_i\circ R^{a_i n}
 -\prod_{i=1}^d\E[g_i\mid B]\circ R^{a_i n}\right)\right\|_2
 \longrightarrow0.
\end{equation}
\end{lemma}

\begin{proposition}[Selected laws]\label{prop:selected}
Formula~\eqref{eq:selected-law} defines a probability measure
$\lambda_Y$ on $Y^I$ with the following properties.
\begin{enumerate}
\item Every marginal is $m_Y$, and $\lambda_Y$ is invariant under
$(y_i)_i\mapsto(S_Y^{it}y_i)_i$ for every $t\in\R$.
If $\theta:Y'\to Y$ is an extension over $C$, then
$(\theta^I)_*\lambda_{Y'}=\lambda_Y$.  These projections also hold
for countable inverse limits of extensions.
\item The law $\Lambda_Y$ of $P$ is its deterministic-length law:
for bounded $H_i$ on $W_Y$,
\begin{equation}\label{eq:ordinary-parameter-law}
 \int\prod_iH_i(w_i)\,\dd\Lambda_Y
 =\lim_{L\to\infty}\int_Y\frac1L\int_0^L
       \prod_i H_i(\omega_Y(S_Y^{it}y))\,\dd t\,\dd m_Y(y).
\end{equation}
\item For every proper subset $J\subsetneq I$, the conditional law
of $(y_i)_{i\in J}$ given the \emph{entire} parameter array $P$ is
\begin{equation}\label{eq:proper-fibres}
 \operatorname{Law}_{\lambda_Y}\bigl((y_i)_{i\in J}\mid P\bigr)
 =\bigotimes_{i\in J}m_{Y,P_i}.
\end{equation}
\end{enumerate}
In a countable inverse limit, functions pulled back from the selected
laws at finite stages are dense in the $L^2$ space of the limiting
selected law.
\end{proposition}

\begin{theorem}[Tensor packing]\label{thm:packing}
There is a universal constant $C$ with the following property.  Let
$0<\varepsilon\le1$, $d\ge1$, and $L\ge0$ be given, with $d,L$ integers.
Let $x_1,\ldots,x_m$ and $y_1,\ldots,y_m$ lie in the unit balls of real
Hilbert spaces $H_1,H_2$.  For each family suppose that a graph on
$\{1,\ldots,m\}$ of maximum degree at most $L$ contains every off-diagonal
pair whose absolute inner product exceeds $\eta$, where
\[
                         0\le\eta\le\varepsilon^2/10^4.
\]
The two exceptional graphs may differ.  For every orthogonal projection
$P$ on $H_1\otimes H_2$ of rank at most $d$,
\begin{equation}\label{eq:packing-quantitative}
 \#\{n:\norm{P(x_n\otimes y_n)}\ge\varepsilon\}
 \le \frac{C(1+L)}{\varepsilon^2}
       \exp\!\left(C\varepsilon^{-2}\sqrt d\log(2+d)\right).
\end{equation}
In particular, for
\begin{equation}\label{eq:packing-dimension}
                  d_m=\left\lceil(1+\log m)^{3/2}\right\rceil,
\end{equation}
the left side is $o_{\varepsilon,L}(m)$, uniformly over the Hilbert
spaces, the vectors, the projections, and the allowed values of $\eta$.
\end{theorem}

\begin{lemma}[A Gaussian matrix estimate]\label{lem:packing-gaussian}
Let $B_1,\ldots,B_r$ be matrices between two finite-dimensional real
Hilbert spaces, and put
\[
 H_j=\begin{pmatrix}0&B_j\\ B_j^*&0\end{pmatrix},
 \qquad S=\sum_{j=1}^r H_j^2.
\]
If $\norm S_{\rm op}\le\sqrt d$ and $\tr S\le2d$ for some $d\ge1$, then
for independent standard normal variables $g_j$,
\begin{equation}\label{eq:packing-gaussian-bound}
       \E\left\|\sum_{j=1}^r g_jB_j\right\|_{\rm op}
             \le C d^{1/4}\sqrt{\log(2+d)}.
\end{equation}
The constant does not depend on the dimensions of the two spaces.
\end{lemma}

\begin{proposition}\label{prop:role-bound}
Every nonzero correlation \eqref{eq:role-correlation} has at most two
output roles. In particular, the maximal number $r$ just defined
satisfies $r\le2$.
\end{proposition}

\begin{proposition}\label{prop:saturation}
Every standard flow over $C$ has a standard extension $Y$ with the
following property. For every further standard extension
$\rho:Y'\to Y$ over $C$, every $f\in L^2(\lambda_Y)$, and every
$l\in\{0\}\cup I$,
\begin{equation}\label{eq:saturation-identity}
 \E_{\lambda_{Y'}}[f\circ\rho^I\mid\mathcal D_l(Y')]
 =\E_{\lambda_Y}[f\mid\mathcal D_l(Y)]\circ\rho^I.
\end{equation}
If the initial flow is a channel, the extension is a channel with the
same outputs pulled back to it.
\end{proposition}

\begin{lemma}\label{lem:regrouped-channel}
With these outputs and groups, $Z$ is a channel over its slot-$b$
copy of $C$.
\end{lemma}

\begin{lemma}\label{lem:square-conditional}
In the square just defined, the conditional law of column $b$ given
$E$ is its $\lambda_Y$ law given $p$. Moreover,
\begin{equation}\label{eq:square-row-locality}
 \E_{\lambda_Z}[q(\mathbf z_b)\mid E,(y_i)_{i\in I}]
       =u(E_b,y_b).
\end{equation}
In particular, the conditional law of $y_b$ given $E$ is
$m_Y(\dd y\mid w)$; in a single $Z$-state, the conditional law of its
slot-$b$ state given $e=\omega_Z$ is the same fibre law over its old
slot-$b$ parameter.
\end{lemma}

\begin{lemma}\label{lem:parameter-reanchoring}
Under $\lambda_Z$, the variables $p$ and $E_b$ are conditionally independent
given $w=P_{bb}$.
\end{lemma}

\begin{lemma}\label{lem:independent-hilbert-vectors}
Let $V$ be a square-integrable random vector in a separable real
Hilbert space, and let $V'$ be an independent copy. If
$\ip V{V'}=0$ almost surely, then $V=0$ almost surely.
\end{lemma}

\begin{proposition}\label{prop:activation}
For the saturated channel $Y$ and maximal nonzero correlation chosen
above, the regrouped channel $Z$ has a nonzero correlation
\eqref{eq:role-correlation} with output roles $A\cup\{b\}$.
\end{proposition}

\begin{lemma}[The two earliest increments on depth inputs]
\label{lem:hbase-X-output}
On each original summation cell \(I\), put \(s=s(I)\), its original
spatial depth in \(J\).  At a finite terminal level \(n\), write \(g_{e,n,I}\) for the last
fit in slot \(e\) at or before \(n\), or zero if there is none, and
put \(r_{e,n,I}=F_{e,s}-g_{e,n,I}\).  For \(u<t\) with
\(\iota(u)=i\ne j=\iota(t)\), let \(a,b\) be the other slots and set
\begin{equation}
 \begin{aligned}
 X_i^{u,t}&=g_{u,I}-g_{u-4,I},&
 X_j^{u,t}&=g_{t,I}-g_{t-4,I},\\
 X_a^{u,t}&=F_{a,s}-g_{a,\mathrm{prev},I},&
 X_b^{u,t}&=F_{b,s}-g_{b,\mathrm{prev},I}.
 \end{aligned}                                                   \label{eq:hbase-X}
\end{equation}
Here \(g_{e,\mathrm{prev},I}\) is the last fit in slot \(e\) strictly
before \(t\), or zero.  In original slot order,
\begin{equation}
 H_I(F_{\cdot,s})
  =\sum_{\substack{1\le u<t\le n\\\iota(u)\ne\iota(t)}}
       H_I(X^{u,t}_I)+\mathrm{Rem}_{n,I},\qquad
 \sum_{I\in\mathcal U}|I||\mathrm{Rem}_{n,I}|\longrightarrow0     \label{eq:hbase-X-remainder}
\end{equation}
for every fixed finite \(\mathcal U\subseteq\mathcal I\).
The remainder is the term with four \(r_{e,n,I}\)'s plus, for each
slot \(e\), the term with \(g_{e,n,I}\) there and \(r_{l,n,I}\) in
the other three slots.

For sufficiently large \(A\), there is an absolute
\(0<\theta_0<A^{-7}<1\) such that, whenever \(t\ge12\), every pair
of factors \(X_l^{u,t}\) has form norm at most
\(e^{-2k_t^{\theta_0}}\).  All four factors have bounded normalized
\(L^2(I)\) size.
\end{lemma}

\begin{lemma}[A separated scale sum on depth inputs]
\label{lem:hbase-scale}
For the fixed separated term above, let both opponents be admissible
on \(K\) with parameters \(D_{\rm h},L\).  For
\(m\in\mathbb Z_{\ge0}\), let \(\mathcal U_m\subseteq\mathcal U\)
consist of any selected cells on which
\(e^{-m-1}<A_{|I|}\le e^{-m}\).  Then
\begin{equation}
 \sum_{I\in\mathcal U_m}|I|
   |H_I(\psi_a z_{a,I},\psi_b z_{b,I};Q)|
 \le e^{-m}\operatorname{poly}
       \bigl(1+m,\log(2H),\log(2D_{\rm h}),1+L\bigr)|K|.       \label{eq:hbase-scale-sum}
\end{equation}
These bands cover every positive \(A_{|I|}\).  If \(A_{|I|}=0\),
the corresponding two-input form vanishes.
\end{lemma}

\begin{lemma}[A compact Gevrey bump]
\label{lem:ergodic-bump}
There is a real nonnegative \(\rho\in C_c^\infty(\mathbb R)\), supported
in \([-1,1]\), with integral \(1\), whose derivatives obey a bound of
the form \eqref{eq:profile-derivatives} for some constant \(G\geq1\).
\end{lemma}

\begin{lemma}[Bounds for the private catalog]
\label{lem:row-catalog}
For every dyadic cell $Q\subset R$ and every vector
$a=(a_v)_{v\in\mathcal V(Q)}$, one has
\begin{equation}
 D^{-1}\|a\|_{\ell^2}
 \le \left\|\sum_{v\in\mathcal V(Q)}a_v\Phi_v(y)\right\|_{\mathcal H}
 \le D^{3/2}\|a\|_{\ell^2}
 \quad\hbox{for almost every }y\in Q.
 \label{eq:row-catalog-comparison}
\end{equation}
In particular constant coefficients in such a representation are
unique.  Coefficients may be regarded as vectors in the one space
$\ell^2(\mathcal V)$ by extending them by zero; the vector for a
combination on $Q$ is unchanged when the combination is restricted
to a descendant.

These assertions and the same value of $D$ hold after restriction to
a dyadic subroot $R'\subset R$: discard birth cells disjoint from
$R'$, give an inherited label with $R'\subset J_v$ the new birth
cell $R'$, and retain the other birth cells contained in $R'$.
\end{lemma}

\begin{lemma}[The depth-varying row estimate]
\label{lem:row-depth}
Let the root, catalog, partitions, and rows satisfy every hypothesis
of Lemma~\ref{lem:row-maximal}.  Let $(F_s)_{s\in\mathsf S}$ satisfy
Equation~\eqref{eq:row-input-normalization} on $R$.  Choose
$s_n\in\mathsf S$ with
$s_1\le s_2\le\cdots\le s_N$, and let every row of round $n$
read the same input $F_{s_n}$.  These read indices label the input
schedule independently of the spatial depths of the support cells.  Then
\begin{equation}
 \left(\sum_{n=1}^N\sum_{\nu\in\mathcal R_n}
          \|A_\nu F_{s_n}\|_{\mathcal Y_\nu}^2\right)^{1/2}
 \le \mathfrak C_D B\,|R|^{1/2}
 \le \frac{40}{3} B\log_2(2D)\,|R|^{1/2}.
 \label{eq:row-depth}
\end{equation}
The constant is independent of the number of rows, depths, and
input blocks.
\end{lemma}

\begin{corollary}[Increments of inherited projections]
\label{cor:row-projections}
Use the catalog of Lemma~\ref{lem:row-catalog}.  On a finite
interval of integers $h\ge s_R$, let $\mathcal P_h$ be the full
partition of $R$ into cells of depth $h$.  On each
$Q\in\mathcal P_h$, let $P_{h,Q}$ be the orthogonal projection in
$L^2(Q;\mathcal H)$ onto constant-coefficient combinations of
a subset $\mathcal M_h(Q)\subset\mathcal V(Q)$.  Assume inheritance:
if $Q'\in\mathcal P_{h+1}$ is contained in $Q$, then
$\mathcal M_h(Q)\subset\mathcal M_{h+1}(Q')$.  Let $P_h$ be the
direct sum of the $P_{h,Q}$ on $L^2(R;\mathcal H)$.

Suppose $(F_s)_{s\in\mathsf S}$ satisfies
Equation~\eqref{eq:row-input-normalization}.  For any integer $J\ge1$ and
\[
 r_1\le t_1\le r_2\le t_2\le\cdots\le r_J\le t_J
\]
in the projection depth range and nondecreasing
$s_1,\ldots,s_J\in\mathsf S$, one has
\begin{equation}
 \sum_{j=1}^J\|(P_{t_j}-P_{r_j})F_{s_j}\|_2^2
 \le \mathfrak C_D^2|R|.
 \label{eq:row-disjoint-increments}
\end{equation}
If the intervals can be divided into $\mathfrak m$ such ordered
families whose reads are nondecreasing, the right side is multiplied
by $\mathfrak m$.

For each $s\in\mathsf S$ with $s\ge s_R$, let $\mathcal U_s$ be any
subcollection of the depth-$s$ cells of $R$.  In particular fix an integer
$\ell$ and retain only those $s$ for which $s+\ell$ and $s+\ell+1$ are in
the projection range.  Then
\begin{equation}
 \sum_s\sum_{I\in\mathcal U_s}|I|\,
       \|(P_{s+\ell+1}-P_{s+\ell})F_s\|_{2,I}^2
 \le \mathfrak C_D^2|R|.
 \label{eq:row-increment}
\end{equation}
For every integer $L\ge0$, retaining only $s\in\mathsf S$ with $s\ge s_R$
for which $s$ and $s+L$ are in the projection range,
\begin{equation}
 \left(\sum_s\sum_{I\in\mathcal U_s}|I|\,
       \|(P_{s+L}-P_s)F_s\|_{2,I}^2\right)^{1/2}
 \le L\mathfrak C_D|R|^{1/2}
 \le (1+L)\mathfrak C_D|R|^{1/2}.
 \label{eq:row-delay}
\end{equation}
\end{corollary}

\begin{lemma}[Rolling an axis into the local state]\label{lem:rolled-extension}
Let $R\subset I$ satisfy $|R|\leq k-2$, and choose $a\in I\setminus R$.
There is an extension of the saturated object whose local state is
$Y'=Y^I$, with local law $m_1$, parameter
\begin{equation}\label{eq:rolled-parameter}
 u'((y_c)_{c\in I})=((u(y_c))_{c\in I},(y_c)_{c\in R}),
\end{equation}
and factor map $(y_c)_{c\in I}\mapsto y_a$.
Its level-$n$ law is $m_{n+1}$, with the first axis treated as internal
to the local state, and its time transformation is componentwise $T_Y$.
\end{lemma}

\begin{lemma}[Parameter geometry]\label{lem:parameter-geometry}
In the level-two parameter law, for every $a\in I$ and every proper
set $J\subset I$,
\begin{equation}\label{eq:parameter-geometry}
 \Law((q_j)_{j\in J}\mid p_a)
 =\bigotimes_{j\in J}K_a(p_a[j],\dd q_j).
\end{equation}
In particular, for each $i\in I$, the diagonal row and column tuples
$p_i,q_i$ are conditionally independent, with the same law
$K_i(u,\cdot)$, given their common coordinate $u=u_{i,i}$.
\end{lemma}

\begin{lemma}[The rectangle identities]\label{lem:rectangle}
For the grouped square just described, almost surely in $(z,c,d,x,y)$,
\begin{equation}\label{eq:rectangle-identities}
 L_A(x)J_t(d)=J_s(c)L_B(y),\qquad
 L_A(x)^*J_s(c)=J_t(d)L_B(y)^*.
\end{equation}
The identities also hold in every ordering of the row and column groups.
\end{lemma}

\begin{lemma}[Projection of tensor contractions]\label{lem:contraction-completeness}
In any three-cell row of the grouped square, abbreviate the cell spaces
by $H_r,H_s,H_t$ and their common-active projections by $P_r,P_s,P_t$.
For $g\in H_s$, $h\in H_t$, set
\[
 C_r(g,h)=\E[g(Y_s)h(Y_t)\mid Y_r].
\]
Then
\begin{equation}\label{eq:contraction-projections}
 P_rC_r(g,h)=C_r(g,P_th)=C_r(P_sg,h)=C_r(P_sg,P_th).
\end{equation}
The contractions with both inputs in their $D$ spaces lie in $D_r$ and
span it.  The same assertions hold for each grouped column.
Moreover, with $h(z)$ from Lemma~\ref{lem:polar-group},
\begin{equation}\label{eq:corner-completeness}
 D_{P,r}=L^2(\sigma(h(z))).
\end{equation}
Consequently the intersection at every grouped cell is spanned by lines
exact simultaneously for its three-cell row and column laws.
\end{lemma}

\begin{lemma}[Active-space exactness]\label{lem:active-exact}
For $\pi$-almost every $p$ and every $i\in I$,
\begin{equation}\label{eq:active-exact}
 \Ran\Pi_i(p)=C_i(p).
\end{equation}
\end{lemma}

\begin{proposition}[Orbit cancellation]
\label{prop:orbit-cancellation}
Assume that $X$ is a mixing two-sided finite-alphabet stationary process whose
alphabet partition has entropy rate zero. For every centered finite-valued
one-site function $f$ on $X$, every probability coupling $x:Y\to X$, every
family satisfying \eqref{eq:projective-characters}, every automorphism $G$,
and every $l\in L$, one has
\begin{equation}
 \label{eq:orbit-cancellation}
 \lim_{N\to\infty}\frac1N\sum_{r=0}^{N-1}
 \left|\int f(T_X^r x)\overline{\chi_{G^r l}}\dd\eta\right|=0.
\end{equation}
\end{proposition}

\begin{lemma}[Orbit alternatives]
\label{lem:orbit-alternatives}
Let $G$ be an automorphism of an abelian group $L$ and $l\in L$.
At least one of the following holds:
\begin{enumerate}
\item The sequence $(G^r l)_{r\ge0}$ is dissociated.
\item There is $p\ge1$ such that $(G^{pm+j}l)_{m\ge0}$ is dissociated
      for every $0\le j<p$.
\item There are $p,d\ge1$ such that, on the subgroup
      $K=\langle G^r l:r\in\Z\rangle$, the endomorphism
      $N=G^p-\id$ satisfies $N^d=0$. In this case
      \begin{equation}
       \label{eq:binomial-orbit}
       G^{pm+j}l
       =\sum_{a=0}^{d-1}\binom ma N^aG^j l
       \qquad(m\ge0,\ 0\le j<p).
      \end{equation}
\end{enumerate}
\end{lemma}

\begin{theorem}
\label{thm:main}
Set $k=2^{75}$. For every integer $N\ge1$, every $p\in(0,1)$, and every
family $\mathcal D\subseteq2^{[N]}$,
\[
\mu_p(\mathcal D)\ge1-\frac1k
\quad\Longrightarrow\quad
E_k(\mathcal D)\text{ is }p\text{-small}.
\]
\end{theorem}

\begin{proposition}\label{prop:half-density}
Let $L=2^{70}$. For every integer $N\ge1$, every $q\in(0,1)$, and every
$\mathcal F\subseteq 2^{[N]}$ satisfying $\mu_q(\mathcal F)\ge1/2$,
the family $E_{32}(\mathcal F)$ is $(q/L)$-small.
\end{proposition}

\begin{lemma}[A real-line test]
\label{lem:tr-real}
Let \(0\leq k_-\leq k_+\), and partition
\(\{k_-,\ldots,k_+\}\) into \(w\) nonempty consecutive blocks.
Suppose that bounded Borel functions \(h_1,h_2,h_3\) and
\(h_{0,k}\) are supported in a common interval of length \(L>0\),
that \(|h_j|\leq1\) for \(1\leq j\leq3\), and that
\(\mathcal V_{B_0}(h_0)\leq w^{-1/2}\) on every block \(B_0\).
Then
\begin{equation}
 \left|\sum_{k=k_-}^{k_+}\int_{\R^2}
 h_{0,k}(x)\prod_{j=1}^3h_j(x+b_jt)\Delta_k(t)\,dx\,dt\right|
 \leq C_{\varphi,b}(L+D2^{k_+}).
 \label{eq:tr-real}
\end{equation}
The constant is independent of the scale range, partition, and inputs.
\end{lemma}

\begin{lemma}[An integer-sequence test]
\label{lem:tr-integer}
Under the scale and block hypotheses of Lemma~\ref{lem:tr-real},
let \(h_1,h_2,h_3\) and \(h_{0,k}\) instead be sequences on \(\Z\),
supported in a common integer interval of cardinality \(L\geq1\).
Assume the same pointwise size and block variation bounds.  Then
\begin{equation}
 \left|\sum_{k=k_-}^{k_+}\sum_{m,n\in\Z}
 h_{0,k}(m)\prod_{j=1}^3h_j(m+b_jn)\Delta_k(n)\right|
 \leq C'_{\varphi,b}(L+D2^{k_+}).
 \label{eq:tr-integer}
\end{equation}
\end{lemma}

\begin{proposition}[Finite orbit oscillation]
\label{prop:tr-oscillation}
For every deterministic list \(0\leq k_1<\cdots<k_{w+1}\),
\begin{equation}
 \sum_{i=1}^w\int_X
 \max_{k_i\leq\ell\leq k_{i+1}}
       |V_\ell^\varphi-V_{k_i}^\varphi|\,d\mu
 \leq C''_{\varphi,b}\sqrt w.
 \label{eq:tr-oscillation}
\end{equation}
This holds on every invertible probability preserving system, with a
constant independent of that system, the functions, and the endpoints.
\end{proposition}

\begin{lemma}[Norm convergence at distinct slopes]
\label{lem:tr-norm}
If \(S\) is mixing, \(a_1,\ldots,a_r\) are distinct nonzero
integers, and \(g_1,\ldots,g_r\) are bounded measurable functions,
then
\begin{equation}
 \frac1N\sum_{n=1}^N\prod_{j=1}^rg_j\circ S^{a_jn}
 \longrightarrow\prod_{j=1}^r\int_Xg_j\,d\mu
 \quad\text{in }L^2(\mu).
 \label{eq:tr-norm}
\end{equation}
Consequently, for \(F_n\) in \eqref{eq:tr-orbit-averages} and
\(p=\prod_{j=1}^3\int_Xf_j\,d\mu\), every
\(\chi\in C_c^1(\R)\) of integral one satisfies
\begin{equation}
 \sum_{n\in\Z}a^{-1}\chi(n/a)F_n\longrightarrow p
 \quad\text{in }L^2(\mu),\qquad a\to\infty.
 \label{eq:tr-weighted-norm}
\end{equation}
\end{lemma}
